ALTER POLICY "Own conversations update" ON public.ai_conversations USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid() AND (business_id IS NULL OR EXISTS (SELECT 1 FROM public.businesses b WHERE b.id = ai_conversations.business_id AND b.owner_id = auth.uid())));
ALTER POLICY "Own diagnostics insert" ON public.diagnostics WITH CHECK (user_id = auth.uid() AND (conversation_id IS NULL OR EXISTS (SELECT 1 FROM public.ai_conversations c WHERE c.id = diagnostics.conversation_id AND c.user_id = auth.uid())));
ALTER POLICY "Own plans insert" ON public.action_plans WITH CHECK (user_id = auth.uid() AND (diagnostic_id IS NULL OR EXISTS (SELECT 1 FROM public.diagnostics d WHERE d.id = action_plans.diagnostic_id AND d.user_id = auth.uid())));
ALTER POLICY "Own steps update" ON public.action_plan_steps USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid() AND EXISTS (SELECT 1 FROM public.action_plans p WHERE p.id = action_plan_steps.plan_id AND p.user_id = auth.uid()));